import React,{useEffect,useMemo,useRef,useState} from 'react';
import {createRoot} from 'react-dom/client';
import {ArrowDownLeft,ArrowUpRight,ArrowRight,ArrowLeft,Plus,ChevronLeft,ChevronRight,ChevronDown,LayoutDashboard,ArrowLeftRight,CalendarDays,ChartNoAxesCombined,Settings,LogOut,Wallet,Search,Download,SlidersHorizontal,MoreHorizontal,Check,CheckCheck,X,Copy,Trash2,Pencil,Fuel,Utensils,ShoppingBag,House,Heart,GraduationCap,Receipt,TrendingUp,ShieldCheck,Mail,LockKeyhole,Info,LoaderCircle,RefreshCw,Eye,EyeOff,ChevronUp,CheckCircle2,Coins,Menu} from 'lucide-react';
import {newId,CATEGORIES,METHODS,FREQUENCIES,WEEKDAYS,payWeekday,withPayWeekday,COLORS,today,monthOf,shiftMonth,monthLabel,dayLabel,money,parseMoney,validDate,defaultConfig,payDates,summarize,summarizeYear,categoryTotals,chartPoints,toCSV} from './finance.mjs';
import {supabase,readDemo,saveDemo,demoData,loadAccount,emptyProfile} from './data.mjs';
import {AnnualDashboard,SummaryCards} from './AnnualDashboard.jsx';
import {buildReport,reportCSV,reportPDF,downloadFile} from './reports.mjs';
